classdef CaseEntries
    %CASEENTRIES Manifest entries written out as JSON text, for the tests.
    %
    % Each method returns a column cell of char, one entry per row, as the
    % entry would stand in a manifest file. DECODE turns rows into entries
    % the way the exporter reads the manifest (jsondecode). Numbers are
    % given as texts, as in every other entry.

    methods (Static)

        function lines = logcalls()
            % The logcalls entries, as JSON text, one per row.
            lines = { ...
                '{"name": "ext_log_01", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "s", "calls": [{"op": "log", "args": ["v=%d\n", {"double": ["3"]}]}]}'; ...
                '{"name": "ext_log_02", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "log", "args": ["lost\n"]}, {"op": "openLogKeep", "args": []}, {"op": "log", "args": ["a\n"]}, {"op": "log", "args": ["b\n"]}, {"op": "closeLog", "args": []}, {"op": "log", "args": ["c\n"]}, {"op": "openLog", "args": []}, {"op": "log", "args": ["d\n"]}, {"op": "log", "args": ["e\n"]}]}'; ...
                '{"name": "ext_log_03", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "s", "calls": [{"op": "warning", "args": ["Some:id", "some message"]}]}'; ...
                '{"name": "ext_log_04", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["Some:id", "some message"]}]}'; ...
                '{"name": "ext_log_05", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["", "msg"]}]}'; ...
                '{"name": "ext_log_06", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["id", "50% done"]}]}'; ...
                '{"name": "ext_log_07", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["id", "a\\b"]}]}'; ...
                '{"name": "ext_log_08", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["only"]}, {"op": "warning", "args": ["a", "b", "c"]}]}'; ...
                '{"name": "ext_log_09", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOCONSOLEONLY", "sessionName": "s", "calls": [{"op": "warning", "args": ["only"]}, {"op": "warning", "args": ["id:x", "text %d", {"double": ["5"]}]}]}'; ...
                '{"name": "ext_log_10", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "", "calls": [{"op": "log", "args": ["x\n"]}]}'; ...
                '{"name": "ext_log_11", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": null, "calls": [{"op": "openLog", "args": []}]}'; ...
                '{"name": "ext_log_12", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "NONE", "sessionName": "s", "calls": [{"op": "log", "args": ["x\n"]}, {"op": "warning", "args": ["id", "msg"]}]}'; ...
                '{"name": "ext_log_13", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "openLogKeep", "args": []}, {"op": "warning", "args": ["A:b", "line1\nline2\n"]}, {"op": "log", "args": ["after\n"]}]}'; ...
                '{"name": "ext_log_14", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "s", "calls": [{"op": "openLog", "args": []}, {"op": "openLogKeep", "args": []}, {"op": "log", "args": ["x\n"]}, {"op": "log", "args": ["y\n"]}]}'; ...
