                '{"name": "ext_log_20", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "s", "calls": [{"op": "openLogKeep", "args": []}, {"op": "log", "args": ["%s\n", "\u00e9"]}]}'; ...
                '{"name": "ext_log_21", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "LOGTOFILEONLY", "sessionName": "a/b", "calls": []}'; ...
                '{"name": "ext_log_22", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "<scratch>/elsewhere", "calls": []}'; ...
                '{"name": "ext_log_23", "kind": "logcalls", "exporterChange": "new kind logcalls", "logmode": "BOTH", "sessionName": "C:x", "calls": []}'};
        end

