        function lines = inputsetcall()
            % The inputsetcall entries, as JSON text, one per row.
            lines = { ...
                '{"name": "ext_inputset_08", "kind": "inputsetcall", "exporterChange": "new kind inputsetcall", "logmode": "BOTH", "args": [["modelFilePath", "<scratch>/missing.inp"], ["modelID", "TUTORIAL1"]]}'; ...
