                '{"name": "ext_inputset_10", "kind": "inputsetcall", "exporterChange": "new kind inputsetcall", "logmode": "NONE", "args": [["modelFilePath", ""]]}'; ...
                '{"name": "ext_inputset_11", "kind": "inputsetcall", "exporterChange": "new kind inputsetcall", "logmode": "BOTH", "args": [["sessionParentDir", "<scratch>/missing"]]}'; ...
                '{"name": "ext_inputset_12", "kind": "inputsetcall", "exporterChange": "new kind inputsetcall", "logmode": "BOTH", "args": [["sessionParentDir", "<scratch>/afile"]]}'; ...
