                '{"name": "ext_inputset_25", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/bc_unused.inp", "logmode": "LOGTOFILEONLY", "capture": "files"}'; ...
                '{"name": "ext_inputset_26", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/bc_unused.inp", "logmode": "BOTH", "capture": "console"}'; ...
                '{"name": "ext_inputset_27", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/bc_unused.inp", "logmode": "BOTH", "capture": "files"}'; ...
