                '{"name": "ext_inputset_29", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/bc_zero_power.inp", "logmode": "BOTH", "capture": "files"}'; ...
