                '{"name": "ext_inputset_31", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["cases/input-fixture/ext_inputset_unused_options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "logmode": "NONE", "capture": "console"}'; ...
                '{"name": "ext_inputset_32", "kind": "inputsetwarnings", "exporterChange": "new kind inputsetwarnings", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["cases/input-fixture/ext_inputset_unused_geom.inp", "TUTORIAL1"], "logmode": "NONE", "capture": "console"}'};
