        function lines = inputset()
            % The inputset entries, as JSON text, one per row.
            lines = { ...
                '{"name": "ext_inputset_01", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "upstream/openstream/inputs/tutorial1.inp", "logmode": "LOGTOFILEONLY"}'; ...
                '{"name": "ext_inputset_02", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "upstream/openstream/inputs/tutorial1.inp", "logmode": "LOGTOCONSOLEONLY"}'; ...
                '{"name": "ext_inputset_03", "kind": "inputset", "logmode": "BOTH"}'; ...
                '{"name": "ext_inputset_04", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/ext_inputset_mine.inp", "logmode": "NONE"}'; ...
                '{"name": "ext_inputset_05", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/ext_inputset_two.dots.inp", "logmode": "NONE"}'; ...
                '{"name": "ext_inputset_06", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/.ext_inputset_hidden.inp", "logmode": "NONE"}'; ...
                '{"name": "ext_inputset_07", "kind": "inputset", "geometry": ["cases/input-fixture/ext_bc_geometry_one.inp", "G1"], "bc": "cases/input-fixture/ext_inputset_mesh.inp", "logmode": "NONE"}'; ...
                '{"name": "ext_inputset_20", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "cases/input-fixture/ext_inputset_nodot", "logmode": "BOTH"}'; ...
                '{"name": "ext_inputset_22", "kind": "inputset", "model": ["upstream/openstream/inputs/models.inp", "TUTORIAL1"], "options": ["upstream/openstream/inputs/options.inp", "DEFAULT"], "geometry": ["upstream/openstream/inputs/geom.inp", "TUTORIAL1"], "bc": "upstream/openstream/inputs/tutorial2_transient.inp", "logmode": "NONE"}'};
