        function lines = write()
            % The write entries, as JSON text, one per row.
            lines = { ...
                '{"name": "ext_write_01", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "values": [["PERIM", {"matrix": {"rows": 2, "double": ["1", "3", "2", "4"]}}]]}], "exporterChange": "write values: key matrix: reshape(doubles, rows, []) (column-major)"}'; ...
                '{"name": "ext_write_02", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "mode": "w", "values": [["LENGTH", {"double": ["5.5"]}]]}], "exporterChange": "write calls: field mode (the fopen mode, default a+)"}'; ...
                '{"name": "ext_write_03", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "mode": "a", "values": [["LENGTH", {"double": ["5.5"]}]]}], "exporterChange": "write calls: field mode (the fopen mode, default a+)"}'; ...
                '{"name": "ext_write_04", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "mode": "r+", "values": [["LENGTH", {"double": ["5.5"]}]]}], "exporterChange": "write calls: field mode (the fopen mode, default a+)"}'; ...
                '{"name": "ext_write_05", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "values": [["PERIM", {"text": ""}]]}], "exporterChange": "write values: text '''' written once as a char and once as a string"}'; ...
                '{"name": "ext_write_06", "kind": "write", "class": "Geometry", "calls": [{"id": "G", "values": [["PERIM", {"array": {"dims": [1, 2, 2], "double": ["1", "2", "3", "4"]}}]]}], "exporterChange": "write values: key array: reshape(doubles, dims) (column-major)"}'};
        end

        function lines = withNul()
            % The one entry with a NUL character in a name (the JSON
            % escape \u0000), kept apart: reading it is tested on its own.
            lines = {'{"name": "ext_session_18", "kind": "sessionfs", "exporterChange": "new kind sessionfs", "logmode": "BOTH", "dirName": "a\u0000b", "overwrite": false, "before": "absent", "parent": "exists"}'};
        end

        function lines = group(kind)
            % The rows of the entries of KIND (a kind name).
            switch kind
                case 'logcalls'
                    lines = TestData.CaseEntries.logcalls();
                case 'sessionfs'
                    lines = TestData.CaseEntries.sessionfs();
                case 'inputsetcall'
                    lines = TestData.CaseEntries.inputsetcall();
                case 'inputsetwarnings'
                    lines = TestData.CaseEntries.inputsetwarnings();
                case 'inputset'
                    lines = TestData.CaseEntries.inputset();
                case 'write'
                    lines = TestData.CaseEntries.write();
                otherwise
                    error('CaseEntries:noKind', 'No entries of kind %s', kind);
            end
        end

        function e = entry(kind, name)
            % The decoded entry NAME of the entries of KIND.
            e = TestData.CaseEntries.named(TestData.CaseEntries.group(kind), name);
        end

        function line = row(kind, name)
            % The JSON text of the entry NAME of the entries of KIND.
            line = TestData.CaseEntries.lineOf(TestData.CaseEntries.group(kind), name);
        end

        function entries = decode(lines)
            % The entries of the rows LINES, as a 1xN cell of the structs
            % jsondecode returns.
            entries = cellfun(@jsondecode, reshape(lines, 1, []), ...
                'UniformOutput', false);
        end

        function e = named(lines, name)
            % The decoded entry of LINES called NAME.
            entries = TestData.CaseEntries.decode(lines);
            names = cellfun(@(x) char(x.name), entries, 'UniformOutput', false);
            index = find(strcmp(names, name));
            if numel(index) ~= 1
                error('CaseEntries:noEntry', 'No single entry named %s', name);
            end
            e = entries{index};
        end

        function line = lineOf(lines, name)
            % The JSON text of the row of LINES called NAME.
            index = find(contains(lines, ['"name": "' name '"']));
            if numel(index) ~= 1
                error('CaseEntries:noEntry', 'No single row named %s', name);
            end
            line = lines{index};
        end

    end

end
